import heapq

def match(orders):
    trades = []
    seq = 0
    order_info = {}  # id -> {'side':..., 'price':..., 'qty':..., 'active': bool}
    bids = []  # heap of (-price, seq, id) for resting buy orders
    asks = []  # heap of (price, seq, id) for resting sell orders

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            info = order_info.get(oid)
            if info and info['active']:
                info['active'] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        seq += 1
        remaining = qty

        if side == 'buy':
            opp = asks
        else:
            opp = bids

        while remaining > 0 and opp:
            top = opp[0]
            if side == 'buy':
                top_price = top[0]
            else:
                top_price = -top[0]
            top_id = top[2]
            info = order_info.get(top_id)
            if not info or not info['active'] or info['qty'] <= 0:
                heapq.heappop(opp)
                continue

            if typ != 'market':
                if side == 'buy':
                    if top_price > price:
                        break
                else:
                    if top_price < price:
                        break

            heapq.heappop(opp)
            trade_qty = min(remaining, info['qty'])
            if side == 'buy':
                trades.append([oid, top_id, top_price, trade_qty])
            else:
                trades.append([top_id, oid, top_price, trade_qty])
            remaining -= trade_qty
            info['qty'] -= trade_qty
            if info['qty'] > 0:
                heapq.heappush(opp, top)
            else:
                info['active'] = False

        if typ == 'limit' and remaining > 0:
            order_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True}
            if side == 'buy':
                heapq.heappush(bids, (-price, seq, oid))
            else:
                heapq.heappush(asks, (price, seq, oid))
        else:
            if typ == 'limit':
                order_info[oid] = {'side': side, 'price': price, 'qty': 0, 'active': False}

    return trades

